func TestRawClient_Do_DoesNotCloseSeekableReaderBody(t *testing.T) {
	t.Parallel()

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.Copy(io.Discard, r.Body)
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(srv.Close)

	raw, err := NewRawClient(srv.URL, srv.Client())
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	file := tempFileWithContent(t, "payload")
	if err := raw.Do(context.Background(), http.MethodPost, "/files", nil, file, nil); err != nil {
		t.Fatalf("Do error: %v", err)
	}

	// The caller owns the reader: it must still be usable (and closable)
	// after the request, so a retry can rewind it.
	if _, err := file.Seek(0, io.SeekStart); err != nil {
		t.Fatalf("seek after request: %v", err)
	}
	if err := file.Close(); err != nil {
		t.Fatalf("close after request: %v", err)
	}
}

